import '@testing-library/jest-dom/vitest';
import { router as coreRouter } from '@inertiajs/core';
import type * as InertiaReact from '@inertiajs/react';
import { cleanup, configure } from '@testing-library/react';
import { afterEach, beforeEach, vi } from 'vitest';

// The app marks elements with data-test, not the library's data-testid default.
configure({ testIdAttribute: 'data-test' });

// Every form submits through router.visit. Replacing it lets tests read the
// outgoing payload and drive the success and error callbacks by hand.
vi.mock('@inertiajs/react', async (importOriginal) => {
    const actual = await importOriginal<typeof InertiaReact>();
    const { inertiaPage } = await import('./inertia-page');

    return {
        ...actual,
        router: { ...actual.router, visit: vi.fn() },
        // Head needs the head manager that createInertiaApp installs, which no
        // component test bootstraps. Nothing asserts on document.title.
        Head: () => null,
        usePage: () => inertiaPage,
    };
});

// Base UI popups and sliders measure and capture pointers. jsdom implements
// none of it, so the bare minimum is stubbed here.
class ResizeObserverStub {
    observe(): void {}
    unobserve(): void {}
    disconnect(): void {}
}

globalThis.ResizeObserver ??= ResizeObserverStub as never;

Element.prototype.scrollIntoView ??= function scrollIntoView() {};
document.elementFromPoint ??= function elementFromPoint() {
    return null;
};
Element.prototype.getAnimations ??= function getAnimations() {
    return [];
};
Element.prototype.hasPointerCapture ??= function hasPointerCapture() {
    return false;
};
Element.prototype.setPointerCapture ??= function setPointerCapture() {};
Element.prototype.releasePointerCapture ??= function releasePointerCapture() {};

globalThis.matchMedia ??= ((query: string) => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: () => {},
    removeListener: () => {},
    addEventListener: () => {},
    removeEventListener: () => {},
    dispatchEvent: () => false,
})) as never;

beforeEach(() => {
    // Link reaches the core router directly, so the mock on the copy
    // re-exported from @inertiajs/react never sees the call. Nothing boots an
    // Inertia app in a component test, and a real visit throws on the page it
    // has not got.
    vi.spyOn(coreRouter, 'visit').mockImplementation(() => {});
    vi.spyOn(coreRouter, 'prefetch').mockImplementation(() => {});
});

afterEach(() => {
    cleanup();

    // The router mock is created inside a vi.mock factory, which the
    // restoreMocks option does not reach, so its calls are cleared by hand.
    vi.clearAllMocks();
});

/**
 * Backing store for the mocked `usePage`. Page tests assign the props their
 * component reads before rendering it, and `url` for anything that highlights
 * the current route.
 */
export const inertiaPage: { props: Record<string, unknown>; url: string } = {
    props: {},
    url: '/',
};

import type { VisitOptions } from '@inertiajs/core';
import { router } from '@inertiajs/react';
import { act, render, screen } from '@testing-library/react';
import { userEvent } from '@testing-library/user-event';
import type { ReactNode } from 'react';
import type { DefaultValues, FieldValues } from 'react-hook-form';
import { vi } from 'vitest';
import type { ZodType, z } from 'zod';
import { Form } from '@/components/form/form';

export const TEST_ACTION = { url: '/test', method: 'post' } as const;

export const SUBMIT_LABEL = 'Save';

type RenderFormOptions<TSchema extends ZodType<unknown, FieldValues>> = {
    schema: TSchema;
    defaultValues: DefaultValues<z.input<TSchema> & FieldValues>;
    children: ReactNode;
};

export function renderForm<TSchema extends ZodType<unknown, FieldValues>>({
    schema,
    defaultValues,
    children,
}: RenderFormOptions<TSchema>) {
    const user = userEvent.setup();

    render(
        <Form
            action={TEST_ACTION}
            schema={schema}
            defaultValues={defaultValues}
        >
            {children}
            <button type="submit">{SUBMIT_LABEL}</button>
        </Form>,
    );

    return { user };
}

export async function submitForm(
    user: ReturnType<typeof userEvent.setup>,
): Promise<void> {
    await user.click(screen.getByRole('button', { name: SUBMIT_LABEL }));
}

function lastVisit(): [string, VisitOptions] {
    const calls = vi.mocked(router.visit).mock.calls;

    if (calls.length === 0) {
        throw new Error(
            'The form did not submit. Validation most likely rejected the values.',
        );
    }

    return calls[calls.length - 1] as [string, VisitOptions];
}

/** The payload the form last handed to Inertia. */
export function submittedData(): Record<string, unknown> {
    return lastVisit()[1].data as Record<string, unknown>;
}

export function submittedUrl(): string {
    return lastVisit()[0];
}

export function didSubmit(): boolean {
    return vi.mocked(router.visit).mock.calls.length > 0;
}

/** Replays a Laravel 422 response through the callbacks Inertia would have called. */
export async function respondWithErrors(
    errors: Record<string, string>,
): Promise<void> {
    const [, options] = lastVisit();

    await act(async () => {
        options.onError?.(errors);
        options.onFinish?.({} as never);
    });
}

export async function respondWithSuccess(): Promise<void> {
    const [, options] = lastVisit();

    await act(async () => {
        options.onSuccess?.({} as never);
        options.onFinish?.({} as never);
    });
}

import type { Table } from '@tanstack/react-table';
import { render, screen, within } from '@testing-library/react';
import { userEvent } from '@testing-library/user-event';
import type { ReactNode } from 'react';
import type { DataTableBaseProps } from '@/components/data-table/data-table';
import { DataTable } from '@/components/data-table/data-table';
import type { DataTableColumn } from '@/components/data-table/types';
import type { UseDataTableOptions } from '@/components/data-table/use-data-table';
import { useDataTable } from '@/components/data-table/use-data-table';

export type Person = {
    id: string;
    name: string;
    email: string;
    age: number;
};

export const people: Person[] = [
    { id: '1', name: 'Ada Lovelace', email: 'ada@example.com', age: 36 },
    { id: '2', name: 'Grace Hopper', email: 'grace@example.com', age: 45 },
    { id: '3', name: 'Alan Turing', email: 'alan@example.com', age: 41 },
];

export const personColumns: DataTableColumn<Person>[] = [
    { accessorKey: 'name', header: 'Name' },
    { accessorKey: 'email', header: 'Email' },
    { accessorKey: 'age', header: 'Age', meta: { align: 'end' } },
];

export type HarnessOptions = Partial<UseDataTableOptions<Person>>;

type HarnessProps = {
    options?: HarnessOptions;
    children: (table: Table<Person>) => ReactNode;
};

function TableHarness({ options, children }: HarnessProps) {
    const table = useDataTable<Person>({
        data: people,
        columns: personColumns,
        getRowId: (person) => person.id,
        ...options,
    });

    return children(table);
}

/** Renders whatever a test needs around one live table instance. */
export function renderWithTable(
    children: (table: Table<Person>) => ReactNode,
    options?: HarnessOptions,
) {
    const user = userEvent.setup();

    const result = render(
        <TableHarness options={options}>{children}</TableHarness>,
    );

    return { user, ...result };
}

/** The common case: the component under test is the table itself. */
export function renderDataTable(
    props?: DataTableBaseProps<Person>,
    options?: HarnessOptions,
) {
    return renderWithTable(
        (table) => <DataTable table={table} {...props} />,
        options,
    );
}

function textOf(element: HTMLElement): string {
    return element.textContent?.trim() ?? '';
}

export function headerTexts(): string[] {
    return screen.getAllByRole('columnheader').map(textOf);
}

export function bodyRows(): HTMLElement[] {
    // The head is the first rowgroup, the body the second.
    const [, body] = screen.getAllByRole('rowgroup');

    return within(body).queryAllByRole('row');
}

export function rowTexts(): string[][] {
    return bodyRows().map((row) =>
        within(row).getAllByRole('cell').map(textOf),
    );
}

export function columnTexts(index: number): string[] {
    return rowTexts().map((cells) => cells[index] ?? '');
}
